import { readFileSync, writeFileSync } from "node:fs";
const root = new URL("../", import.meta.url),
  read = (name) => readFileSync(new URL(name, root), "utf8");
const html = read("web/index.html")
  .replace("/*TEAM_STYLE*/", () => read("web/style.css"))
  .replace("/*TEAM_SCRIPT*/", () => read("web/app.js"));
if (html.includes("</script><script"))
  throw Error("Unexpected script boundary");
writeFileSync(
  new URL("src/ui.generated.ts", root),
  "// Generated by scripts/build-ui.mjs; edit web/ instead.\nexport const HTML = " +
    JSON.stringify(html) +
    ";\n",
);
